class Solution {
    struct SumMultiset {
        multiset<long long> nums;
        long long sum = 0;
        void insert(long long val) {
            nums.insert(val);
            sum += val;
        }
        void erase(long long val) {
            auto it = nums.find(val);
            if (it != nums.end()) {
                nums.erase(it);
                sum -= val;
            }
        }
        long long getMax() const {
            return nums.empty() ? 0 : *nums.rbegin();
        }
        long long getMin() const {
            return nums.empty() ? 0 : *nums.begin();
        }
        size_t size() const {
            return nums.size();
        }
    };

public:
    long long minOperations(vector<int>& nums, int k) {
        SumMultiset below, above;
        int target = (k + 1) / 2;

        auto balance = [&]() {
            while ((int)below.size() > target) {
                long long v = below.getMax();
                below.erase(v);
                above.insert(v);
            }
            while ((int)below.size() < target && above.size() > 0) {
                long long v = above.getMin();
                above.erase(v);
                below.insert(v);
            }
        };

        auto add = [&](long long val) {
            if (below.size() == 0 || val <= below.getMax()) {
                below.insert(val);
            } else {
                above.insert(val);
            }
            balance();
        };

        auto remove = [&](long long val) {
            if (below.nums.find(val) != below.nums.end()) {
                below.erase(val);
            } else {
                above.erase(val);
            }
            balance();
        };

        auto getCost = [&]() -> long long {
            long long median = below.getMax();
            return (median * below.size() - below.sum) + (above.sum - median * above.size());
        };

        for (int i = 0; i < k; ++i) add(nums[i]);
        long long ans = getCost();

        for (int i = k; i < (int)nums.size(); ++i) {
            add(nums[i]);
            remove(nums[i - k]);
            ans = min(ans, getCost());
        }
        return ans;
    }
};

class Solution {
    private PriorityQueue<Long> small = new PriorityQueue<>(Collections.reverseOrder());
    private PriorityQueue<Long> large = new PriorityQueue<>();
    private Map<Long, Integer> delayed = new HashMap<>();
    private int smallSize = 0, largeSize = 0;
    private long sumSmall = 0, sumLarge = 0;
    private int target;

    public long minOperations(int[] nums, int k) {
        target = (k + 1) / 2;
        for (int i = 0; i < k; ++i) add(nums[i]);
        long ans = getCost();

        for (int i = k; i < nums.length; ++i) {
            add(nums[i]);
            remove(nums[i - k]);
            ans = Math.min(ans, getCost());
        }
        return ans;
    }

    private void prune(PriorityQueue<Long> heap) {
        while (!heap.isEmpty()) {
            long val = heap.peek();
            int count = delayed.getOrDefault(val, 0);
            if (count > 0) {
                delayed.put(val, count - 1);
                heap.poll();
            } else break;
        }
    }

    private void balance() {
        while (smallSize > target) {
            prune(small);
            long val = small.poll();
            sumSmall -= val;
            smallSize--;
            large.offer(val);
            sumLarge += val;
            largeSize++;
            prune(small);
        }
        while (smallSize < target && largeSize > 0) {
            prune(large);
            long val = large.poll();
            sumLarge -= val;
            largeSize--;
            small.offer(val);
            sumSmall += val;
            smallSize++;
            prune(large);
        }
    }

    private void add(long num) {
        prune(small);
        if (small.isEmpty() || num <= small.peek()) {
            small.offer(num);
            sumSmall += num;
            smallSize++;
        } else {
            large.offer(num);
            sumLarge += num;
            largeSize++;
        }
        balance();
    }

    private void remove(long num) {
        prune(small);
        delayed.put(num, delayed.getOrDefault(num, 0) + 1);
        if (num <= small.peek()) {
            smallSize--;
            sumSmall -= num;
            if (num == small.peek()) prune(small);
        } else {
            largeSize--;
            sumLarge -= num;
            if (!large.isEmpty() && num == large.peek()) prune(large);
        }
        balance();
    }

    private long getCost() {
        prune(small);
        prune(large);
        long median = small.peek();
        return (median * smallSize - sumSmall) + (sumLarge - median * largeSize);
    }
}

var minOperations = function(nums, k) {
    const target = Math.floor((k + 1) / 2);
    const window = [];

    function insertSorted(arr, val) {
        let l = 0, r = arr.length;
        while (l < r) {
            const mid = (l + r) >> 1;
            if (arr[mid] < val) l = mid + 1;
            else r = mid;
        }
        arr.splice(l, 0, val);
    }

    function removeSorted(arr, val) {
        let l = 0, r = arr.length;
        while (l < r) {
            const mid = (l + r) >> 1;
            if (arr[mid] < val) l = mid + 1;
            else r = mid;
        }
        arr.splice(l, 1);
    }

    for (let i = 0; i < k; ++i) insertSorted(window, nums[i]);

    function getCost() {
        const median = window[target - 1];
        let cost = 0;
        for (let i = 0; i < k; ++i) {
            cost += Math.abs(window[i] - median);
        }
        return cost;
    }

    let ans = getCost();
    for (let i = k; i < nums.length; ++i) {
        insertSorted(window, nums[i]);
        removeSorted(window, nums[i - k]);
        ans = Math.min(ans, getCost());
    }
    return ans;
};
